/**
 * @ingroup iface_zaura_output
 * @struct zaura_output_interface
 */
struct zaura_output_interface {
	/**
	 * destroy zaura_output
	 *
	 * Destroy this zaura_shell object.
	 *
	 * Destroying a bound zaura_shell object while there are
	 * zaura_surfaces still alive created by this zaura_shell object
	 * instance is illegal and will result in a protocol error.
	 *
	 * See zaura_shell.release for destructor naming.
	 * @since 38
	 */
	void (*release)(struct wl_client *client,
			struct wl_resource *resource);
};

