{
	wl_resource_post_event(resource_, ZAURA_OUTPUT_LOGICAL_TRANSFORM, transform);
}

/**
 * @ingroup iface_zaura_output
 * Sends an display_id event to the client owning the resource.
 * @param resource_ The client's resource
 */
static inline void
zaura_output_send_display_id(struct wl_resource *resource_, uint32_t display_id_hi, uint32_t display_id_lo)
{
	wl_resource_post_event(resource_, ZAURA_OUTPUT_DISPLAY_ID, display_id_hi, display_id_lo);
}

/**
 * @ingroup iface_zaura_output
 * Sends an activated event to the client owning the resource.
 * @param resource_ The client's resource
 */
static inline void
zaura_output_send_activated(struct wl_resource *resource_)
{
	wl_resource_post_event(resource_, ZAURA_OUTPUT_ACTIVATED);
}

