/**
 * @ingroup iface_zaura_toplevel
 * @struct zaura_toplevel_interface
 */
struct zaura_toplevel_interface {
	/**
	 * set orientation lock for a remote surface
	 *
	 * Request a specific orientation behavior when this surface is
	 * in fullscreen.
	 * @since 26
	 */
	void (*set_orientation_lock)(struct wl_client *client,
				     struct wl_resource *resource,
				     uint32_t orientation_lock);
	/**
	 * surface will be submitted in pixel coordinates
	 *
	 * Informs the server that when submitting this surface, this
	 * client will not use wl_surface_set_buffer_scale to report the
	 * scales, nor will it apply scale via vp_viewporter. Instead the
	 * server should apply an appropriate scale transform for the
	 * submitted buffers to be composited correctly.
	 * @since 28
	 */
	void (*surface_submission_in_pixel_coordinates)(struct wl_client *client,
							struct wl_resource *resource);
	/**
	 * enables screen coordinates in window bounds
	 *
	 * Requesting this will enable screen coordinates in surfaces
	 * associated with aura_toplevel including sub surfaces and popup
	 * windows who added this toplevel as a parent. This should be set
	 * before first commit.
	 * @since 29
	 */
	void (*set_supports_screen_coordinates)(struct wl_client *client,
						struct wl_resource *resource);
	/**
	 * set window size and position
	 *
	 * Request a new location and bounds of the surface in DP screen
	 * coordinates. The size will be applied to visible bounds used in
	 * set_geometry. The output is a hint for the compositor to
	 * determine which output the window should move to. If the output
	 * is null, the compositor should make decision solely by the given
	 * bounds. These parameters are just a request and the compositor
	 * may ignore, adjust the size and position based on the rule
	 * imposed by the window manager, or may preserve it for future
	 * operations. For example, the compositor will not allow a
	 * position outside of the output, or the compositor may just store
	 * it if the toplevel surface is in maximiezd state, and may use it
	 * upon unmaximized.
	 * @param output the output
	 * @since 29
	 */
	void (*set_window_bounds)(struct wl_client *client,
				  struct wl_resource *resource,
				  int32_t x,
				  int32_t y,
				  int32_t width,
				  int32_t height,
				  struct wl_resource *output);
	/**
	 * set session id and restore id
	 *
	 * Request session id and restore id of a newly created browser
	 * window. Set the information used by compositor to restore the
	 * toplevel surface state, such as window position, window state,
	 * upon creation. This is not double buffered and must be set
	 * before sending first commit.
	 * @param restore_session_id unique browser session id
	 * @param restore_window_id restore browser window id
	 * @since 30
	 */
	void (*set_restore_info)(struct wl_client *client,
				 struct wl_resource *resource,
				 int32_t restore_session_id,
				 int32_t restore_window_id);
	/**
	 * make window a system modal
	 *
	 * Requests that the toplevel surface should become a system
	 * modal. The compositor will prevent other windows from receiving
	 * events. If there are multiple system modal surfaces, the
	 * compositor will decide which one to receive events.
	 * @since 31
	 */
	void (*set_system_modal)(struct wl_client *client,
				 struct wl_resource *resource);
	/**
	 * unset window system modal state
	 *
	 * Requests that the system modal state of the toplevel surface
	 * will be unset. The compositor will then allow other windows to
	 * recieve events.
	 * @since 31
	 */
	void (*unset_system_modal)(struct wl_client *client,
				   struct wl_resource *resource);
	/**
	 * set session id and restore window id source
	 *
	 * Request session id and restore id of the window. Set the
	 * information used by compositor to restore the toplevel surface
	 * state, such as window position, window state, upon creation.
	 * This is not double buffered and must be set before sending first
	 * commit. This is different from set_restore_info, used for
	 * clients that create multiple windows associated with
	 * restore_id_source.
	 * @param restore_session_id unique browser session id
	 * @param restore_window_id_source restore window id source
	 * @since 32
	 */
	void (*set_restore_info_with_window_id_source)(struct wl_client *client,
						       struct wl_resource *resource,
						       int32_t restore_session_id,
						       const char *restore_window_id_source);
	/**
	 * request a decoration for surface
	 *
	 * Clients are allowed to request a particular decoration for a
	 * zaura_toplevel. The server is not required to honor this
	 * request. See decoration_type for available options. Available
	 * since M105.
	 * @param type the new frame type
	 * @since 35
	 */
	void (*set_decoration)(struct wl_client *client,
			       struct wl_resource *resource,
			       uint32_t type);
	/**
	 * destroy zaura_toplevel
	 *
	 * Destroy this zaura_toplevel object. A client should call
	 * destroy when the role is unmapped from a wl_surface.
	 *
	 * See zaura_shell.release for destructor naming.
	 * @since 38
	 */
	void (*release)(struct wl_client *client,
			struct wl_resource *resource);
	/**
	 * float the surface on top
	 *
	 * [Deprecated] Use set_float_to_location. This is a request to
	 * place the surface above others.
	 * @since 39
	 */
	void (*set_float)(struct wl_client *client,
			  struct wl_resource *resource);
	/**
	 * unset the surface float
	 *
	 * Request that the surface resets floating.
	 * @since 39
	 */
	void (*unset_float)(struct wl_client *client,
			    struct wl_resource *resource);
	/**
	 * set z order for window
	 *
	 * Sets the z order for a toplevel surface. See z_order_level for
	 * available options.
	 * @param z_order z order value for the window
	 * @since 40
	 */
	void (*set_z_order)(struct wl_client *client,
			    struct wl_resource *resource,
			    uint32_t z_order);
	/**
	 * set window position in DPs
	 *
	 * Request a new location for the surface in device-independent
	 * pixels (DPs), relative to the top-left corner of the given
	 * output.
	 *
	 * A null output means whichever output currently contains the
	 * surface.
	 *
	 * These parameters are just a request and the compositor may
	 * ignore them, adjust them due to rules imposed by the window
	 * manager, or preserve them for future operations. For example,
	 * the compositor will not allow a position outside of the output;
	 * or the compositor may just store it if the toplevel surface is
	 * in maximized state, and may use it upon unmaximize.
	 * @param output output to contain the surface
	 * @since 41
	 */
	void (*set_origin)(struct wl_client *client,
			   struct wl_resource *resource,
			   int32_t x,
			   int32_t y,
			   struct wl_resource *output);
	/**
	 * activates the window
	 *
	 * Activates this window. This is equivalent to bringing the
	 * window to the foreground. The compositor is free to ignore this
	 * request if it deems the client to be misbehaving.
	 * @since 42
	 */
	void (*activate)(struct wl_client *client,
			 struct wl_resource *resource);
	/**
	 * deactivates the window
	 *
	 * Deactivates this window. This is equivalent to requesting that
	 * the window not be the foreground window. The exact behavior is
	 * compositor-defined. The compositor is free to ignore this
	 * request if it deems the client to be misbehaving.
	 * @since 42
	 */
	void (*deactivate)(struct wl_client *client,
			   struct wl_resource *resource);
	/**
	 * Sets the behavior of the surface in fullscreen.
	 *
	 * Suggests how the windowing manager should behave if this
	 * surface were to go fullscreen. Does not make the surface
	 * fullscreen.
	 * @since 44
	 */
	void (*set_fullscreen_mode)(struct wl_client *client,
				    struct wl_resource *resource,
				    uint32_t mode);
	/**
	 * Allows the client to set the scale factor for the future buffer commits.
	 *
	 * The client has a 32-bit float scale factor that is associated
	 * with each zaura toplevel. This scale factor must be propagated
	 * exactly to exo. To do so we reinterpret_cast into a 32-bit uint
	 * and later cast back into a float. This is because wayland does
	 * not support native transport of floats. As different CPU
	 * architectures may use different endian representations for IEEE
	 * 754 floats, this protocol implicitly assumes that the caller and
	 * receiver are the same machine. To avoid redundant messages, this
	 * request needs to only be called once when the zaura toplevel
	 * scale factor changes. This is double buffered state and will be
	 * applied in the next commit.
	 * @since 46
	 */
	void (*set_scale_factor)(struct wl_client *client,
				 struct wl_resource *resource,
				 uint32_t scale_factor_as_uint);
	/**
	 * snap the surface to the primary snap position.
	 *
	 * Request that surface is snapped to the left or top if primary
	 * layout, right or bottom otherwise.
	 * @since 48
	 */
	void (*set_snap_primary)(struct wl_client *client,
				 struct wl_resource *resource,
				 uint32_t snap_ratio_as_uint);
	/**
	 * snap the surface to the secondary snap position.
	 *
	 * Request that surface is snapped to the right or bottom if
	 * primary layout, left or top otherwise.
	 * @since 48
	 */
	void (*set_snap_secondary)(struct wl_client *client,
				   struct wl_resource *resource,
				   uint32_t snap_ratio_as_uint);
	/**
	 * client intents to snap the surface.
	 *
	 * Notify (or inform) the server the client's intent to snap the
	 * window. To inform it's no longer willing to snap, send 'none'.
	 * @since 49
	 */
	void (*intent_to_snap)(struct wl_client *client,
			       struct wl_resource *resource,
			       uint32_t direction);
	/**
	 * Unset the window snap.
	 *
	 * Request that window unsets snapping.
	 * @since 49
	 */
	void (*unset_snap)(struct wl_client *client,
			   struct wl_resource *resource);
	/**
	 * Describes if the window is persistable
	 *
	 * Request the persistable status of a window. Sets the
	 * persistable status of the window in its window properties.
	 * Should be called before first commit.
	 * @param persistable is the argument persistable
	 * @since 52
	 */
	void (*set_persistable)(struct wl_client *client,
				struct wl_resource *resource,
				uint32_t persistable);
	/**
	 * set the shape of the surface in DP
	 *
	 * Sets the shape of the toplevel window in DP. Passing NULL will
	 * reset the shape of the window.
	 *
	 * This should be used only in support of the existing (deprecated)
	 * Chrome Apps SetShape API and not for any other purpose.
	 * @since 53
	 */
	void (*set_shape)(struct wl_client *client,
			  struct wl_resource *resource,
			  struct wl_resource *region);
	/**
	 * set top inset to the surface
	 *
	 * Sets the top inset to the surface. This represents the header
	 * height and should be non negative.
	 * @param height Top inset of client window. Should be non negative.
	 * @since 55
	 */
	void (*set_top_inset)(struct wl_client *client,
			      struct wl_resource *resource,
			      int32_t height);
	/**
	 * status of rotate focus event
	 *
	 * If the focus has been successfully rotated between UI elements
	 * inside surface, client replies with 'handled'. If the focus
	 * didn't rotate, the client reply with 'not_handled'. A server may
	 * use this to move the focus to next focusable surface.
	 *
	 * Note that a delay in processing in the client could result in
	 * stale acks received by the server.
	 * @param serial serial for the original; rotation event
	 * @param handled whether or not the rotation was successful
	 * @since 56
	 */
	void (*ack_rotate_focus)(struct wl_client *client,
				 struct wl_resource *resource,
				 uint32_t serial,
				 uint32_t handled);
	/**
	 * Hint that the toplevel surface can be maximized
	 *
	 * Hints to the window manager that the toplevel surface can be
	 * maximized.
	 * @since 58
	 */
	void (*set_can_maximize)(struct wl_client *client,
				 struct wl_resource *resource);
	/**
	 * Hint that the toplevel surface should not be maximized
	 *
	 * Hints to the window manager that the toplevel surface should
	 * not be maximized. Note that the window manager might still
	 * request the client to be maximized. In such an event, the client
	 * should respect the window manager's request and maximize. It may
	 * unset the maximized state afterwards.
	 * @since 58
	 */
	void (*unset_can_maximize)(struct wl_client *client,
				   struct wl_resource *resource);
	/**
	 * Hint that the toplevel surface can enter fullscreen
	 *
	 * Hints to the window manager that the toplevel surface can
	 * enter fullscreen.
	 * @since 58
	 */
	void (*set_can_fullscreen)(struct wl_client *client,
				   struct wl_resource *resource);
	/**
	 * Hint that the toplevel surface should not enter fullscreen
	 *
	 * Hints to the window manager that the toplevel surface should
	 * not be enter fullscreen. Note that the window manager might
	 * still request the client enter fullscreen. In such an event, the
	 * client should respect the window manager's request and enter
	 * fullscreen. It may exit fullscreen afterwards.
	 * @since 58
	 */
	void (*unset_can_fullscreen)(struct wl_client *client,
				     struct wl_resource *resource);
	/**
	 * float the surface on top
	 *
	 * This is a request to place the surface above others.
	 * @since 59
	 */
	void (*set_float_to_location)(struct wl_client *client,
				      struct wl_resource *resource,
				      uint32_t mode);
	/**
	 * Request to apply rounded corners to the window of the surface.
	 *
	 * The client specifies the radius of each corner to be applied
	 * to the window in DPs (device independent pixels).
	 *
	 * The window radius is double buffered, and will be applied at the
	 * time wl_surface.commit of the corresponding wl_surface is
	 * called.
	 *
	 * Note: Rounded corner radii affects the wl_surface tree,
	 * including subsurfaces. Once this protocol is called, surfaces
	 * cannot set their own rounded corner bounds because rounded
	 * window bounds will be applied to the whole surface tree.
	 * @since 60
	 */
	void (*set_window_corner_radii)(struct wl_client *client,
					struct wl_resource *resource,
					uint32_t upper_left_radius,
					uint32_t upper_right_radius,
					uint32_t lower_right_radius,
					uint32_t lower_left_radius);
};

